"""Monthly portfolio CVaR glidepath using public ETF closing prices."""

from datetime import datetime
from pathlib import Path
from hashlib import sha256
from io import BytesIO
import json

import numpy as np
import pandas as pd
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy.optimize import brentq, linprog
import yaml
import gzip


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252
TRADE_TOLERANCE = 1e-10
MARKET_HOLIDAYS = AbstractHolidayCalendar(rules=[
    Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
    USMartinLutherKingJr,
    USPresidentsDay,
    GoodFriday,
    USMemorialDay,
    Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
    Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
    USLaborDay,
    USThanksgivingDay,
    Holiday("Christmas", month=12, day=25, observance=nearest_workday),
])
SPECIAL_CLOSURES = pd.DatetimeIndex([
    "2007-01-02",  # Gerald Ford national day of mourning
    "2012-10-29", "2012-10-30",  # Hurricane Sandy
    "2018-12-05",  # George H. W. Bush national day of mourning
    "2025-01-09",  # Jimmy Carter national day of mourning
])


def exchange_sessions(start, end):
    """NYSE Arca equity sessions for the range covered by the closure list."""
    if start.year < 2007 or end.year > 2025:
        raise ValueError("Extend the exchange calendar before using dates outside 2007–2025.")
    holidays = MARKET_HOLIDAYS.holidays(start, end).union(SPECIAL_CLOSURES)
    return pd.bdate_range(start, end).difference(holidays)


def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_prices(tickers, start, end, sessions, settings, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    prefix = "# fetched_at="
    fetched_header = header.decode("utf-8").strip()
    if not fetched_header.startswith(prefix):
        raise ValueError(f"The price snapshot lacks a fetch timestamp: {Path(config_path).name}")
    fetched_at = fetched_header.removeprefix(prefix)
    if datetime.fromisoformat(fetched_at).utcoffset() is None:
        raise ValueError(f"The price snapshot fetch timestamp lacks a time zone: {Path(config_path).name}")
    input_digest = sha256(body).hexdigest()
    with BytesIO(snapshot) as source:
        source.readline()
        prices = pd.read_csv(source, index_col="Date", parse_dates=["Date"])

    prices = prices.loc[:, list(tickers)].sort_index()
    missing = sessions.difference(prices.index)
    unexpected = prices.index.difference(sessions)
    if len(missing) or len(unexpected):
        raise RuntimeError(
            f"ETF dates differ from the exchange calendar. Missing: {missing[:5].strftime('%Y-%m-%d').tolist()}; "
            f"unexpected: {unexpected[:5].astype(str).tolist()}."
        )
    if (
        prices.empty
        or not prices.index.is_unique
        or not np.isfinite(prices.to_numpy()).all()
        or (prices <= 0).any().any()
    ):
        raise RuntimeError("Adjusted ETF closes are missing, invalid, or incomplete.")
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return prices, fetched_at


def cvar_limit(glidepath, signal_date):
    transition = pd.Period(glidepath["transition_date"], freq="M").ordinal
    target = pd.Period(glidepath["target_date"], freq="M").ordinal
    # A month-end signal sets the risk budget for the following holding month.
    holding_month = signal_date.to_period("M").ordinal + 1
    fraction = np.clip((holding_month - transition) / (target - transition), 0.0, 1.0)
    initial = glidepath["initial_cvar_limit"]
    return initial + fraction * (glidepath["terminal_cvar_limit"] - initial)


def maximum_sleeve_weight(sleeve_returns, bill_returns, limit, confidence):
    """Maximize sleeve weight subject to the expected shortfall of empirical losses."""
    n = len(sleeve_returns)
    # Variables are sleeve weight, the loss threshold, and nonnegative tail losses.
    constraints = np.column_stack((bill_returns - sleeve_returns, -np.ones(n), -np.eye(n)))
    tail_mean = np.r_[0.0, 1.0, np.full(n, 1.0 / (n * (1.0 - confidence)))]
    result = linprog(
        c=np.r_[-1.0, np.zeros(n + 1)],
        A_ub=np.vstack((constraints, tail_mean)),
        b_ub=np.r_[bill_returns, limit],
        bounds=[(0.0, 1.0), (None, None)] + [(0.0, None)] * n,
        method="highs",
    )
    if result.status == 2:
        return None
    if not result.success:
        raise RuntimeError(f"CVaR optimization failed: {result.message}")
    return float(np.clip(result.x[0], 0.0, 1.0))


def build_targets(prices, sessions, start, glidepath, lag, benchmark_weights):
    # Use the exchange schedule to find completed months and their fill dates.
    months = sessions.to_period("M")
    month_ends = np.flatnonzero(months[:-1] != months[1:])
    monthly_returns = prices.iloc[month_ends].pct_change(fill_method=None)
    lookback = glidepath["lookback_months"]
    strategy_targets = {}
    benchmark_targets = {}
    for signal_number, signal_pos in enumerate(month_ends):
        fill_pos = signal_pos + lag
        if fill_pos >= len(sessions) or sessions[fill_pos] < start:
            continue
        if signal_number < lookback:
            raise ValueError("The data start does not allow the full warm-up before the first fill.")

        window = monthly_returns.iloc[signal_number - lookback + 1 : signal_number + 1]
        if not np.isfinite(window.to_numpy()).all():
            raise RuntimeError("A monthly return is missing from the CVaR window.")
        exposure = maximum_sleeve_weight(
            window.to_numpy() @ benchmark_weights,
            window.iloc[:, 2].to_numpy(),
            cvar_limit(glidepath, sessions[signal_pos]),
            glidepath["confidence"],
        )
        fill_date = sessions[fill_pos]
        if exposure is None:
            strategy_targets[fill_date] = np.zeros(3)
            print(f"CVAR_FALLBACK_CASH: {fill_date.date()}")
        else:
            target = exposure * benchmark_weights
            target[2] = 1.0 - exposure
            strategy_targets[fill_date] = target
        benchmark_targets[fill_date] = benchmark_weights

    return strategy_targets, benchmark_targets


def plan_rebalance(positions, cash, previous_close, target, fee_rate, cash_buffer):
    """Lock changes in fractional adjusted shares using the prior close."""
    if target.any():
        previous_values = positions * previous_close
        previous_value = cash + previous_values.sum()
        previous_weights = previous_values / previous_value

        def funding_gap(fraction):
            traded_fraction = np.abs(fraction * target - previous_weights).sum()
            return fraction + fee_rate * traded_fraction + cash_buffer - 1.0

        fraction = brentq(funding_gap, 0.0, 1.0 - cash_buffer)
        target_positions = fraction * previous_value * target / previous_close
        share_changes = target_positions - positions
        negligible = np.abs(share_changes) * previous_close <= TRADE_TOLERANCE * previous_value
        share_changes[negligible & (target > 0.0)] = 0.0
    else:
        share_changes = -positions  # A fully cash target closes every open position.
    share_changes.setflags(write=False)
    return share_changes


def settle_rebalance(share_changes, cash, fill_close, fee_rate, date):
    """Price the locked quantities and require sufficient cash for the entire fill."""
    signed_values = share_changes * fill_close
    traded_value = np.abs(signed_values).sum()
    costs = fee_rate * traded_value
    remaining_cash = cash - signed_values.sum() - costs
    if not np.isfinite(remaining_cash) or remaining_cash < 0.0:
        raise RuntimeError(
            f"Fixed-share rebalance on {date.date()} would leave negative or non-finite cash "
            f"({remaining_cash:.8g})."
        )
    return remaining_cash, traded_value


def backtest(prices, start, targets, fee_rate, cash_buffer):
    dates = prices.index
    first = dates.searchsorted(start)
    if first == len(dates):
        raise ValueError("The backtest period must contain at least one exchange session.")
    if first == 0 and dates[0] in targets:
        raise ValueError("The first simulated session needs a preceding close for sizing.")

    cash = previous_value = 1.0
    positions = np.zeros(prices.shape[1])
    closes = prices.to_numpy()
    daily_results = []
    scheduled_shares = None
    for i in range(max(0, first - 1), len(dates)):
        close = closes[i]
        if i >= first:
            turnover = 0.0
            trades = 0
            if scheduled_shares is not None:
                before_fills = cash + positions @ close
                remaining_cash, traded_value = settle_rebalance(scheduled_shares, cash, close, fee_rate, dates[i])
                positions, cash = positions + scheduled_shares, remaining_cash
                turnover = traded_value / before_fills
                trades = int(np.count_nonzero(scheduled_shares))

            value = cash + positions @ close
            daily_results.append((value / previous_value - 1.0, turnover, trades))
            previous_value = value

        if i + 1 < len(dates):
            # Stage the next session's quantities after this close, including the initial fill.
            target = targets.get(dates[i + 1])
            scheduled_shares = (
                plan_rebalance(positions, cash, close, target, fee_rate, cash_buffer)
                if target is not None else None
            )

    return pd.DataFrame(daily_results, index=dates[first:], columns=["return", "turnover", "n_trades"])


def metrics(daily_results, bill_returns):
    returns = daily_results["return"]
    growth = (1.0 + returns).cumprod().to_numpy()
    peak = np.maximum.accumulate(np.r_[1.0, growth])[1:]
    vol = returns.std() * np.sqrt(SESSIONS_PER_YEAR)
    excess = returns - bill_returns.reindex(returns.index)
    excess_vol = excess.std() * np.sqrt(SESSIONS_PER_YEAR)
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1.0) if len(growth) else None,
        "ann_vol": float(vol) if np.isfinite(vol) else None,
        "sharpe": float(returns.mean() * SESSIONS_PER_YEAR / vol) if vol > 0 else None,
        "sharpe_excess": float(excess.mean() * SESSIONS_PER_YEAR / excess_vol) if excess_vol > 0 else None,
        "max_drawdown": float((growth / peak - 1.0).min()) if len(growth) else None,
        "total_return": float(growth[-1] - 1.0) if len(growth) else None,
        "turnover": float(daily_results["turnover"].sum()),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def main():
    config, _ = load_config(str(ROOT / "config.yaml"))
    tickers = tuple(config["universe"][role] for role in ("equity", "bond", "bills"))
    if len(set(tickers)) != len(tickers) or any(not ticker.isalpha() for ticker in tickers):
        raise ValueError("Supply three distinct alphabetic ETF tickers.")
    data_start, start, is_end, end = (
        pd.Timestamp(config["dates"][key])
        for key in ("data_start", "backtest_start", "is_end", "backtest_end")
    )
    if not data_start < start < is_end < end < pd.Timestamp.now(tz="America/New_York").normalize().tz_localize(None):
        raise ValueError("The dates must be ordered and the data interval must be historical.")

    glidepath = config["glidepath"]
    if pd.Period(glidepath["transition_date"], freq="M") >= pd.Period(glidepath["target_date"], freq="M"):
        raise ValueError("The glidepath transition month must precede the target month.")
    if not 0 <= glidepath["terminal_cvar_limit"] < glidepath["initial_cvar_limit"] < 1:
        raise ValueError("CVaR limits must decline from the initial loss cap to the terminal cap.")
    lookback = glidepath["lookback_months"]
    if not 0 < glidepath["confidence"] < 1 or type(lookback) is not int or lookback < 1:
        raise ValueError("Supply a valid CVaR confidence and a positive integer lookback.")

    execution = config["execution"]
    lag = execution["lag_sessions"]
    cost, slippage = execution["cost_bps"], execution["slippage_bps"]
    fee_rate = (cost + slippage) / 10_000.0
    cash_buffer = execution["cash_buffer_bps"] / 10_000.0
    if type(lag) is not int or lag < 1 or min(cost, slippage) < 0 or not 0 <= fee_rate < 1:
        raise ValueError("Supply a positive session lag and valid cost and slippage rates.")
    if not 0 < cash_buffer < 1.0 - fee_rate:
        raise ValueError("Cash buffer must be positive and leave room for estimated costs.")
    equity_weight = config["benchmark"]["equity_weight"]
    if not 0 <= equity_weight <= 1:
        raise ValueError("The benchmark equity weight must be between zero and one.")
    benchmark_weights = np.array([equity_weight, 1.0 - equity_weight, 0.0])

    sessions = exchange_sessions(data_start, end)
    prices, fetched_at = load_prices(tickers, data_start, end, sessions, config, str(ROOT / "config.yaml"))
    bill_returns = prices.iloc[:, 2].pct_change(fill_method=None)
    strategy_targets, benchmark_targets = build_targets(prices, sessions, start, glidepath, lag, benchmark_weights)
    strategy_daily = backtest(prices, start, strategy_targets, fee_rate, cash_buffer)
    benchmark_daily = backtest(prices, start, benchmark_targets, fee_rate, cash_buffer)
    dates = strategy_daily.index
    periods = {
        "is": dates <= is_end,
        "oos": dates > is_end,
        "full": slice(None),
    }
    strategy_metrics = {name: metrics(strategy_daily.loc[mask], bill_returns) for name, mask in periods.items()}
    benchmark_metrics = {name: metrics(benchmark_daily.loc[mask], bill_returns) for name, mask in periods.items()}
    results = {
        "strategy": config["strategy"],
        "data_range": {
            "start": dates[0].date().isoformat(),
            "end": dates[-1].date().isoformat(),
        },
        **strategy_metrics,
        "benchmark": benchmark_metrics["full"],
    }
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust total-return closes; fractional adjusted-share units")
    print("PARAM_COMBOS_TRIED: 1")
    for name in periods:
        print(f"{name.upper()}: {json.dumps(strategy_metrics[name], allow_nan=False)}")
        print(f"BENCHMARK {name.upper()}: {json.dumps(benchmark_metrics[name], allow_nan=False)}")
    print(f"RESULTS_JSON: {json.dumps(results, allow_nan=False)}")


if __name__ == "__main__":
    main()
